import { ApiError, UploadAbortedError, type ApiClient } from "./client";
import { normaliseUsername, usernameProblem } from "../lib/username";
import { DEMO_IDS } from "./demo";
import type {
  Person,
  AnalysisList,
  AnalysisResult,
  AnalysisStatus,
  AnalysisSummary,
  FramesPayload,
  Report,
  User,
} from "./types";

/**
 * Backend stand-in for VITE_USE_MOCKS=true. Serves real pipeline output from
 * /public/mock (generated by scripts/make_mock_fixtures.py) and simulates
 * uploads and the worker's stage progression for newly created analyses.
 * A file whose name contains "fail" fails with NO_PERSON_DETECTED.
 * It starts signed in as MOCK_USER so demos open straight to the app; signing
 * out and in again works in memory with any email and password. New sign-ups
 * start unverified; the token "valid" verifies, resets or confirms an email change, anything
 * else is expired.
 */

export const MOCK_USER: User = {
  id: "mock-user",
  email: "demo@serve-analyzer.dev",
  created_at: "2026-09-20T10:00:00Z",
  email_verified: true,
};

const TEMPLATE_ID = "demo-serve-1";

export const MOCK_STAGES: { status: AnalysisStatus; ms: number }[] = [
  { status: "queued", ms: 1000 },
  { status: "extracting_pose", ms: 3000 },
  { status: "analyzing", ms: 1000 },
  { status: "rendering", ms: 1500 },
];

interface Created {
  summary: AnalysisSummary;
  startedAt: number | null;
  failing: boolean;
}

export interface MockOptions {
  now?: () => number;
  latencyMs?: number;
  fetchJson?: <T>(path: string) => Promise<T>;
}

async function defaultFetchJson<T>(path: string): Promise<T> {
  const res = await fetch(path);
  if (!res.ok) throw new ApiError(res.status, `Mock fixture ${path} not found`);
  return (await res.json()) as T;
}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

export function createMockClient(options: MockOptions = {}): ApiClient {
  const now = options.now ?? Date.now;
  const latency = options.latencyMs ?? 250;
  const fetchJson = options.fetchJson ?? defaultFetchJson;
  const created = new Map<string, Created>();
  let counter = 0;
  let user: User | null = MOCK_USER;
  const deleted = new Set<string>();
  const reports = new Map<string, Report>();
  const notes = new Map<string, string | null>();
  let pendingEmail: string | null = null;
  let profile: {
    username: string | null; display_name: string | null; bio: string | null; avatar_url: string | null; accept_requests: boolean;
    share_stats: boolean; share_positions: boolean; on_leaderboard: boolean;
  } = {
    username: null, display_name: null, bio: null, avatar_url: null, accept_requests: true,
    share_stats: false, share_positions: false, on_leaderboard: false,
  };
  // The pretend friend shares everything, so friends' stats and the leaderboard show in mock mode.
  const ACE_SCORES = [58, 61, 60, 66, 70, 69, 74, 72, 77, 80, 79, 83];
  const aceStats = () => ({
    serves: ACE_SCORES.length,
    average_score: Math.round(ACE_SCORES.slice(-10).reduce((a, b) => a + b, 0) / 10),
    averaged_over: 10,
    best_score: Math.max(...ACE_SCORES),
    trend: ACE_SCORES.map((score, i) => ({ at: new Date(now() - (ACE_SCORES.length - i) * 4 * 86_400_000).toISOString(), score })),
    change: 6,
  });
  const acePositions = {
    front_knee_flexion: { score: 84, measured: 10 }, back_knee_flexion: { score: 71, measured: 9 },
    trunk_tilt: { score: 88, measured: 10 }, elbow_angle: null, wrist_height: { score: 62, measured: 10 },
  };
  // Pretend people for Friends in mock mode: one friend, one request waiting, one to find.
  const people = new Map<string, { display_name: string; bio: string }>([
    ["ace", { display_name: "Alex Ace", bio: "Flat first serve, working on the kick." }],
    ["serve_queen", { display_name: "Serena Q", bio: "Coach. Ask me about the trophy position." }],
    ["taken", { display_name: "Tay Ken", bio: "" }],
  ]);
  const links = new Map<string, { id: string; status: "pending" | "accepted"; direction: "incoming" | "outgoing"; created_at: string; accepted_at: string | null }>([
    ["ace", { id: "c-ace", status: "accepted", direction: "outgoing", created_at: "2026-09-01T10:00:00Z", accepted_at: "2026-09-02T10:00:00Z" }],
    ["serve_queen", { id: "c-queen", status: "pending", direction: "incoming", created_at: "2026-10-10T10:00:00Z", accepted_at: null }],
  ]);
  const blocked = new Map<string, string>();
  // Mock conversations, keyed by the other person's username.
  type MockMessage = { id: string; from_you: boolean; body: string | null; deleted: boolean; created_at: string };
  const chats = new Map<string, { id: string; messages: MockMessage[]; read_at: string | null }>([
    ["ace", {
      id: "conv-ace", read_at: null, messages: [
        { id: "m1", from_you: false, body: "Saw your new serve. The knee bend looks much deeper!", deleted: false, created_at: "2026-10-12T18:00:00Z" },
        { id: "m2", from_you: true, body: "Thanks! Still working on the toss.", deleted: false, created_at: "2026-10-12T18:05:00Z" },
        { id: "m3", from_you: false, body: "Hit on Saturday?", deleted: false, created_at: "2026-10-13T09:00:00Z" },
      ],
    }],
  ]);
  const chatById = (id: string) => {
    const entry = [...chats.entries()].find(([, c]) => c.id === id);
    if (!entry || blocked.has(entry[0])) throw new ApiError(404, "Conversation not found");
    return entry;
  };
  const isFriend = (username: string) => links.get(username)?.status === "accepted";
  function conversationSummary(username: string) {
    const chat = chats.get(username)!;
    const last = chat.messages[chat.messages.length - 1];
    const unread = chat.messages.filter((m) => !m.from_you && !m.deleted && (!chat.read_at || m.created_at > chat.read_at)).length;
    return {
      id: chat.id, person: summaryOf(username), unread, can_send: isFriend(username),
      why_not: isFriend(username) ? null : "You're no longer friends.",
      last_message: last ? { text: last.body?.slice(0, 120) ?? null, from_you: last.from_you, deleted: last.deleted, at: last.created_at } : null,
    };
  }
  const summaryOf = (username: string) => ({ username, display_name: people.get(username)?.display_name ?? null, avatar_url: null });
  function personOf(username: string): Person {
    if (username === profile.username) return { ...summaryOf(username), display_name: profile.display_name, relationship: "self", can_request: false, bio: profile.bio };
    const link = links.get(username);
    const relationship = !link ? "none" : link.status === "accepted" ? "friends" : link.direction === "outgoing" ? "requested" : "incoming";
    return {
      ...summaryOf(username), relationship, connection_id: link?.id ?? null, can_request: relationship === "none",
      bio: relationship === "friends" ? people.get(username)?.bio || null : null,
      friends_since: relationship === "friends" ? link!.accepted_at : null,
      stats: relationship === "friends" && username === "ace" ? aceStats() : null,
      positions: relationship === "friends" && username === "ace" ? acePositions : null,
    };
  }
  function findPerson(username: string): string {
    const name = normaliseUsername(username);
    if ((!people.has(name) && name !== profile.username) || blocked.has(name)) throw new ApiError(404, "No one has that username.");
    return name;
  }
  const usernameOfLink = (id: string) => [...links.entries()].find(([, l]) => l.id === id)?.[0];
  // Pretend someone else has these, so "taken" can be tried in mock mode.
  const takenUsernames = new Set(["taken", "ace", "serve_queen"]);

  const delay = () => (latency > 0 ? sleep(latency) : Promise.resolve());

  function isDemo(id: string): boolean {
    return (DEMO_IDS as readonly string[]).includes(id);
  }

  function current(entry: Created): AnalysisSummary {
    const { summary, startedAt, failing } = entry;
    if (startedAt === null || summary.status === "failed" || summary.status === "succeeded") {
      return summary;
    }
    let elapsed = now() - startedAt;
    for (const stage of MOCK_STAGES) {
      if (elapsed < stage.ms) return { ...summary, status: stage.status };
      if (failing && stage.status === "extracting_pose") {
        entry.summary = {
          ...summary,
          status: "failed",
          error: {
            code: "NO_PERSON_DETECTED",
            message: "We couldn't detect a person clearly. Check the filming guide.",
          },
        };
        return entry.summary;
      }
      elapsed -= stage.ms;
    }
    entry.summary = {
      ...summary,
      status: "succeeded",
      thumbnail_url: `/mock/${TEMPLATE_ID}/thumbnail.jpg`,
      counts: { good: 3, borderline: 2, off: 0, unknown: 5 },
    };
    return entry.summary;
  }

  function entryOrThrow(id: string): Created {
    const entry = created.get(id);
    if (!entry) throw new ApiError(404, "Analysis not found");
    return entry;
  }

  function assertSucceeded(id: string): void {
    if (isDemo(id)) return;
    const status = current(entryOrThrow(id)).status;
    if (status !== "succeeded") throw new ApiError(409, `Analysis is ${status}`);
  }

  return {
    async getMe() {
      await delay();
      return user;
    },

    async signUp({ email }) {
      await delay();
      user = {
        ...MOCK_USER,
        email: email.trim().toLowerCase(),
        created_at: new Date(now()).toISOString(),
        email_verified: false,
      };
      return user;
    },

    async logIn({ email }) {
      await delay();
      user = { ...MOCK_USER, email: email.trim().toLowerCase() };
      return user;
    },

    async logOut() {
      await delay();
      user = null;
    },

    async verifyEmail(token) {
      await delay();
      if (token !== "valid") throw new ApiError(400, "This link is invalid or has expired. Request a new one.");
      if (user) user = { ...user, email_verified: true };
    },

    async resendVerification() {
      await delay();
    },

    async requestPasswordReset() {
      await delay();
    },

    async resetPassword(token) {
      await delay();
      if (token !== "valid") throw new ApiError(400, "This link is invalid or has expired. Request a new one.");
      user = null;
    },

    async deleteAccount(password) {
      await delay();
      if (!password) throw new ApiError(403, "Incorrect password.");
      user = null;
      created.clear();
    },

    async requestEmailChange(newEmail, password) {
      await delay();
      if (!password) throw new ApiError(403, "Incorrect password.");
      const email = newEmail.trim().toLowerCase();
      if (user && email === user.email) throw new ApiError(400, "That's already your email.");
      pendingEmail = email;
    },

    async confirmEmailChange(token) {
      await delay();
      if (token !== "valid" || !pendingEmail) {
        throw new ApiError(400, "This link is invalid or has expired. Request a new one.");
      }
      if (user) user = { ...user, email: pendingEmail, email_verified: true };
      pendingEmail = null;
    },

    async exportData() {
      await delay();
      if (!user) throw new ApiError(401, "Sign in to continue.");
      const { items } = await this.listAnalyses();
      const ts = new Date(now());
      return {
        exported_at: ts.toISOString(),
        links_expire_at: new Date(ts.getTime() + 6 * 3600_000).toISOString(),
        account: { email: user.email, email_verified: user.email_verified ?? false, created_at: user.created_at },
        connections: [...links.entries()].map(([username, l]) => ({ username, status: l.status, direction: l.direction, created_at: l.created_at, accepted_at: l.accepted_at })),
        blocks: [...blocked.entries()].map(([username, at]) => ({ username, blocked_at: at })),
        conversations: [...chats.entries()].map(([username, c]) => ({
          with_username: username,
          messages: c.messages.map(({ from_you, body, deleted, created_at }) => ({ from_you, body, deleted, created_at })),
        })),
        reports_made: [],
        analyses: items.map((a) => ({
          id: a.id,
          filename: a.filename,
          hand: a.hand,
          status: a.status,
          created_at: a.created_at,
          error: a.error ?? null,
          report: reports.get(a.id) ?? null,
          files: {},
        })),
      };
    },

    async getProfile() {
      await delay();
      if (!user) throw new ApiError(401, "Sign in to continue.");
      const { items } = await this.listAnalyses();
      const done = items.filter((a) => a.status === "succeeded");
      const latest = done.map((a) => a.overall_score).filter((s): s is number => s != null).slice(0, 10);
      const best = done.reduce<number | null>((m, a) => (a.overall_score != null && (m == null || a.overall_score > m) ? a.overall_score : m), null);
      return {
        ...profile,
        member_since: user.created_at,
        stats: {
          serves: done.length,
          average_score: latest.length ? Math.round(latest.reduce((a, b) => a + b, 0) / latest.length) : null,
          averaged_over: latest.length,
          best_score: best,
        },
      };
    },

    async updateProfile(body) {
      await delay();
      if (!user) throw new ApiError(401, "Sign in to continue.");
      const next = { ...profile };
      if ("username" in body) {
        const name = normaliseUsername(body.username ?? "");
        const problem = body.username == null ? "A username can be changed but not removed." : usernameProblem(name);
        if (problem) throw new ApiError(422, problem);
        if (takenUsernames.has(name)) throw new ApiError(409, "That username is taken.");
        next.username = name;
      }
      if ("display_name" in body) next.display_name = body.display_name?.trim().replace(/\s+/g, " ") || null;
      if ("bio" in body) next.bio = body.bio?.trim() || null;
      for (const key of ["accept_requests", "share_stats", "share_positions", "on_leaderboard"] as const) {
        if (body[key] != null) next[key] = body[key];
      }
      profile = next;
      return this.getProfile();
    },

    async checkUsername(username) {
      await delay();
      const name = normaliseUsername(username);
      const problem = usernameProblem(name) ?? (takenUsernames.has(name) && name !== profile.username ? "That username is taken." : null);
      return { username: name, available: !problem, problem };
    },

    async setAvatar(jpeg) {
      await delay();
      if (profile.avatar_url) URL.revokeObjectURL(profile.avatar_url);
      profile = { ...profile, avatar_url: URL.createObjectURL(jpeg) };
      return this.getProfile();
    },

    async removeAvatar() {
      await delay();
      if (profile.avatar_url) URL.revokeObjectURL(profile.avatar_url);
      profile = { ...profile, avatar_url: null };
      return this.getProfile();
    },

    async getPerson(username) {
      await delay();
      return personOf(findPerson(username));
    },

    async listConnections() {
      await delay();
      const all = [...links.entries()].map(([username, l]) => ({ ...l, person: summaryOf(username) }));
      return {
        friends: all.filter((c) => c.status === "accepted"),
        incoming: all.filter((c) => c.status === "pending" && c.direction === "incoming"),
        outgoing: all.filter((c) => c.status === "pending" && c.direction === "outgoing"),
      };
    },

    async countRequests() {
      await delay();
      return [...links.values()].filter((l) => l.status === "pending" && l.direction === "incoming").length;
    },

    async sendRequest(username) {
      await delay();
      if (!profile.username) throw new ApiError(409, "Choose a username first, so people know who's asking. You can set one in Settings.");
      const name = findPerson(username);
      if (name === profile.username) throw new ApiError(400, "That's you.");
      const link = links.get(name);
      if (link?.status === "pending" && link.direction === "incoming") {
        links.set(name, { ...link, status: "accepted", accepted_at: new Date(now()).toISOString() });
      } else if (link) {
        throw new ApiError(409, link.status === "accepted" ? "You're already friends." : "You've already sent them a request.");
      } else {
        links.set(name, { id: `c-${name}-${now()}`, status: "pending", direction: "outgoing", created_at: new Date(now()).toISOString(), accepted_at: null });
      }
      return personOf(name);
    },

    async acceptRequest(id) {
      await delay();
      const name = usernameOfLink(id);
      const link = name ? links.get(name) : undefined;
      if (!name || !link || link.status !== "pending" || link.direction !== "incoming") throw new ApiError(404, "Friend request not found");
      const accepted = { ...link, status: "accepted" as const, accepted_at: new Date(now()).toISOString() };
      links.set(name, accepted);
      return { ...accepted, person: summaryOf(name) };
    },

    async removeConnection(id) {
      await delay();
      const name = usernameOfLink(id);
      if (!name) throw new ApiError(404, "Not found");
      links.delete(name);
    },

    async getLeaderboard() {
      await delay();
      const entries = [];
      if (links.get("ace")?.status === "accepted") {
        const ace = aceStats();
        entries.push({ person: summaryOf("ace"), is_you: false, average_score: ace.average_score, scored_serves: ace.serves, needed: 0 });
      }
      if (profile.on_leaderboard) {
        const mine = (await this.listAnalyses()).items.map((a) => a.overall_score).filter((x): x is number => x != null);
        const latest = mine.slice(0, 10);
        entries.push({
          person: { username: profile.username, display_name: profile.display_name, avatar_url: profile.avatar_url }, is_you: true,
          average_score: latest.length >= 5 ? Math.round(latest.reduce((a, b) => a + b, 0) / latest.length) : null,
          scored_serves: mine.length, needed: Math.max(0, 5 - mine.length),
        });
      }
      const ranked = entries.filter((e) => e.needed === 0).sort((a, b) => (b.average_score ?? 0) - (a.average_score ?? 0))
        .map((e, i) => ({ ...e, rank: i + 1 }));
      return { window_days: 90, min_serves: 5, averaged_over: 10, you_are_on_it: profile.on_leaderboard,
        ranked, not_ranked: entries.filter((e) => e.needed > 0).map((e) => ({ ...e, rank: null })) };
    },

    async listConversations() {
      await delay();
      return [...chats.keys()].filter((u) => !blocked.has(u) && chats.get(u)!.messages.length).map(conversationSummary)
        .sort((a, b) => (b.last_message?.at ?? "").localeCompare(a.last_message?.at ?? ""));
    },

    async countUnread() {
      await delay();
      return [...chats.keys()].filter((u) => !blocked.has(u)).reduce((n, u) => n + conversationSummary(u).unread, 0);
    },

    async startConversation(username) {
      await delay();
      const name = findPerson(username);
      if (!chats.has(name)) {
        if (!isFriend(name)) throw new ApiError(403, "You can only message friends.");
        chats.set(name, { id: `conv-${name}`, messages: [], read_at: null });
      }
      return conversationSummary(name);
    },

    async getConversation(id) {
      await delay();
      return conversationSummary(chatById(id)[0]);
    },

    async listMessages(id) {
      await delay();
      const [, chat] = chatById(id);
      return { items: [...chat.messages].reverse(), next_cursor: null, seen_up_to: chat.messages.at(-1)?.created_at ?? null };
    },

    async sendMessage(id, body) {
      await delay();
      const [username, chat] = chatById(id);
      if (!isFriend(username)) throw new ApiError(403, "You can only message friends.");
      const text = body.trim();
      if (!text) throw new ApiError(422, "Write a message first.");
      if (text.length > 2000) throw new ApiError(422, "Messages are up to 2,000 characters.");
      const message = { id: `m-${now()}-${chat.messages.length}`, from_you: true, body: text, deleted: false, created_at: new Date(now()).toISOString() };
      chat.messages.push(message);
      return message;
    },

    async markRead(id) {
      await delay();
      chatById(id)[1].read_at = new Date(now()).toISOString();
    },

    async deleteMessage(messageId) {
      await delay();
      for (const chat of chats.values()) {
        const m = chat.messages.find((x) => x.id === messageId && x.from_you && !x.deleted);
        if (m) {
          Object.assign(m, { body: null, deleted: true });
          return;
        }
      }
      throw new ApiError(404, "Message not found");
    },

    async report() {
      await delay();
    },

    async listBlocks() {
      await delay();
      return [...blocked.entries()].map(([username, at]) => ({ person: summaryOf(username), blocked_at: at }));
    },

    async block(username) {
      await delay();
      const name = findPerson(username);
      links.delete(name);
      blocked.set(name, new Date(now()).toISOString());
    },

    async unblock(username) {
      await delay();
      if (!blocked.delete(normaliseUsername(username))) throw new ApiError(404, "You haven't blocked anyone with that username.");
    },

    async changePassword(currentPassword) {
      await delay();
      if (!currentPassword) throw new ApiError(403, "Incorrect password.");
    },

    async getReport(id) {
      await delay();
      return reports.get(id) ?? null;
    },

    async reportAnalysis(id, body) {
      await delay();
      const report: Report = { reason: body.reason, note: body.note?.trim() || null, created_at: new Date(now()).toISOString() };
      reports.set(id, report);
      return report;
    },

    async deleteAnalysis(id) {
      await delay();
      if (!created.delete(id) && !isDemo(id)) throw new ApiError(404, "Analysis not found");
      deleted.add(id);
    },

    async createAnalysis(body) {
      await delay();
      counter += 1;
      const id = `mock-${counter}`;
      const ts = new Date(now()).toISOString();
      const summary: AnalysisSummary = {
        id,
        hand: body.hand,
        status: "awaiting_upload",
        filename: body.filename,
        created_at: ts,
        updated_at: ts,
        error: null,
        thumbnail_url: null,
        counts: null,
      };
      created.set(id, { summary, startedAt: null, failing: /fail/i.test(body.filename) });
      return {
        analysis: summary,
        upload: {
          url: `mock://upload/${id}`,
          method: "PUT",
          headers: { "Content-Type": body.content_type },
          expires_at: new Date(now() + 15 * 60_000).toISOString(),
        },
      };
    },

    async uploadVideo(_target, file, onProgress, signal) {
      const steps = 20;
      const totalMs = Math.min(3000, 800 + file.size / 50_000);
      for (let i = 1; i <= steps; i++) {
        if (signal?.aborted) throw new UploadAbortedError();
        await sleep(totalMs / steps);
        onProgress(i / steps);
      }
    },

    async startAnalysis(id) {
      await delay();
      const entry = entryOrThrow(id);
      if (entry.summary.status !== "awaiting_upload") {
        throw new ApiError(409, `Analysis is already ${entry.summary.status}`);
      }
      entry.startedAt = now();
      entry.summary = { ...entry.summary, status: "queued" };
      return current(entry);
    },

    async retryAnalysis(id) {
      await delay();
      const entry = entryOrThrow(id);
      if (current(entry).status !== "failed") {
        throw new ApiError(409, "Only failed analyses can be retried");
      }
      entry.failing = false;
      entry.startedAt = now();
      entry.summary = { ...entry.summary, status: "queued", error: null };
      return current(entry);
    },

    async getAnalysis(id) {
      await delay();
      if (deleted.has(id)) throw new ApiError(404, "Analysis not found");
      if (isDemo(id)) return fetchJson<AnalysisSummary>(`/mock/${id}/summary.json`);
      return current(entryOrThrow(id));
    },

    async listAnalyses(_cursor, query = {}) {
      await delay();
      const fixtures = await fetchJson<AnalysisList>("/mock/analyses.json");
      const mine = [...created.values()].map(current).reverse();
      const demos = fixtures.items.filter((a) => !deleted.has(a.id));
      // The same filters the API applies (serve_api/db.py HistoryFilters), in memory.
      const keep = (a: AnalysisSummary) => {
        const t = Date.parse(a.created_at);
        if (query.uploaded_from && t < Date.parse(query.uploaded_from)) return false;
        if (query.uploaded_to && t >= Date.parse(query.uploaded_to)) return false;
        const score = a.overall_score ?? null;
        if (query.min_score && (score === null || score < Number(query.min_score))) return false;
        if (query.max_score && (score === null || score > Number(query.max_score))) return false;
        if (query.stat && query.stat_band) {
          const key = (a.key_scores as Record<string, { band: string } | null> | null | undefined)?.[query.stat];
          if (key?.band !== query.stat_band) return false;
        }
        return true;
      };
      const items = [...mine, ...demos].map((a) => ({ ...a, note: notes.get(a.id) ?? a.note ?? null })).filter(keep);
      return { items, next_cursor: null };
    },

    async setNote(id, note) {
      await delay();
      const trimmed = note.trim();
      if (trimmed) notes.set(id, trimmed);
      else notes.set(id, null);
      const summary = isDemo(id) ? await fetchJson<AnalysisSummary>(`/mock/${id}/summary.json`) : current(entryOrThrow(id));
      return { ...summary, note: notes.get(id) ?? null };
    },

    async getResult(id) {
      await delay();
      assertSucceeded(id);
      const result = await fetchJson<AnalysisResult>(
        `/mock/${isDemo(id) ? id : TEMPLATE_ID}/result.json`,
      );
      return { ...result, id };
    },

    async getFrames(id) {
      await delay();
      assertSucceeded(id);
      return fetchJson<FramesPayload>(`/mock/${isDemo(id) ? id : TEMPLATE_ID}/frames.json`);
    },
  };
}
